<?php
require_once __DIR__.'/auth.php'; require_roles(['Admin']); csrf_verify(); $error='';$message='';
if($_SERVER['REQUEST_METHOD']==='POST') { $username=trim($_POST['username']??'');$password=(string)($_POST['password']??'');$role=$_POST['role']??'';$emp=($_POST['employee_id']??'')===''?null:filter_var($_POST['employee_id'],FILTER_VALIDATE_INT);$validRoles=['Admin','HR','Manager','Employee'];
 if(!preg_match('/^[A-Za-z0-9._-]{3,80}$/',$username)||strlen($password)<12||!in_array($role,$validRoles,true)||($role==='Employee'&&(!$emp||$emp<1))||($role!=='Employee'&&$emp!==null)) $error='Check username, password, role and employee mapping. Password must be at least 12 characters.';
 else { try { if($emp!==null){$check=$conn->prepare("SELECT id FROM employees WHERE id=? AND status='Active'");$check->bind_param('i',$emp);$check->execute();$found=$check->get_result()->fetch_assoc();$check->close();if(!$found)throw new RuntimeException('Choose an active employee.');} $hash=password_hash($password,PASSWORD_DEFAULT);$s=$conn->prepare('INSERT INTO users(username,password_hash,role,employee_id,must_change_password) VALUES(?,?,?,?,1)');$s->bind_param('sssi',$username,$hash,$role,$emp);$s->execute();$s->close();audit_event($conn,'user_created','user',null);header('Location: users.php?created=1');exit;}catch(mysqli_sql_exception $ex){$error=$ex->getCode()===1062?'That username already exists.':'Unable to create account. Check the employee mapping.';}catch(Throwable $ex){$error=$ex->getMessage();}}
}
if(isset($_GET['created']))$message='Account created. The user must change the temporary password on first login.';
$employees=$conn->query("SELECT id,employee_code,full_name FROM employees WHERE status='Active' ORDER BY full_name");$users=$conn->query('SELECT u.id,u.username,u.role,u.is_active,u.last_login,e.employee_code,e.full_name FROM users u LEFT JOIN employees e ON e.id=u.employee_id ORDER BY u.id');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>User administration · HRMS</title><link rel="stylesheet" href="assets.css"></head><body><header><h1>User administration</h1><p>Create accounts and assign least-privilege roles.</p></header><?php include 'nav.php';?><main><?php if($message):?><div class="alert"><?=h($message)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=h($error)?></div><?php endif;?><div class="grid"><section class="panel col-4"><h2>Create account</h2><form method="post"><?=csrf_field()?><div class="field"><label>Username</label><input name="username" minlength="3" maxlength="80" pattern="[A-Za-z0-9._-]+" required></div><div class="field"><label>Temporary password</label><input type="password" name="password" minlength="12" required><small>At least 12 characters; user changes it at first login.</small></div><div class="field"><label>Role</label><select name="role" id="role" required><option>Employee</option><option>Manager</option><option>HR</option><option>Admin</option></select></div><div class="field" id="employee-map"><label>Linked active employee</label><select name="employee_id"><option value="">Choose employee</option><?php while($e=$employees->fetch_assoc()):?><option value="<?=(int)$e['id']?>"><?=h($e['employee_code'].' — '.$e['full_name'])?></option><?php endwhile;?></select></div><button class="btn" type="submit">Create account</button></form></section><section class="panel col-8"><h2>Accounts</h2><div class="table-wrap"><table><thead><tr><th>Username</th><th>Role</th><th>Employee</th><th>Status</th><th>Last login</th></tr></thead><tbody><?php while($u=$users->fetch_assoc()):?><tr><td><?=h($u['username'])?></td><td><?=h($u['role'])?></td><td><?=h($u['employee_code']?($u['employee_code'].' — '.$u['full_name']):'—')?></td><td><?=((int)$u['is_active']===1)?'Active':'Disabled'?></td><td><?=h($u['last_login']??'Never')?></td></tr><?php endwhile;?></tbody></table></div></section></div></main><script>const role=document.getElementById('role'),map=document.getElementById('employee-map'),sel=map.querySelector('select');function sync(){const isEmployee=role.value==='Employee';map.hidden=!isEmployee;sel.required=isEmployee;}role.addEventListener('change',sync);sync();</script></body></html>